package app

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/Antonio7098/ultraplan-go/internal/productstate"
	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
)

type storageMigrationItem struct {
	Kind   string `json:"kind"`
	Scope  string `json:"scope"`
	Path   string `json:"path"`
	Status string `json:"status"`
	Error  string `json:"error,omitempty"`
}

type storageMigrationResult struct {
	SchemaVersion int                    `json:"schema_version"`
	DryRun        bool                   `json:"dry_run"`
	Imported      int                    `json:"imported"`
	Skipped       int                    `json:"skipped"`
	Failed        int                    `json:"failed"`
	Items         []storageMigrationItem `json:"items"`
}

func runStorage(deps dependencies, args []string) error {
	if len(args) == 0 || args[0] == "--help" || args[0] == "-h" {
		_, err := deps.stdout.Write([]byte(storageHelp()))
		return err
	}
	if args[0] != "migrate" {
		return classified(ExitUsage, "storage: expected 'migrate'")
	}
	dryRun, jsonOut := false, false
	for _, arg := range args[1:] {
		switch arg {
		case "--dry-run":
			dryRun = true
		case "--json":
			jsonOut = true
		case "--help", "-h":
			_, err := deps.stdout.Write([]byte(storageHelp()))
			return err
		default:
			return classified(ExitUsage, "storage migrate: unknown argument %q", arg)
		}
	}
	root, err := discoverWorkspace(deps)
	if err != nil {
		return err
	}
	if !dryRun {
		repository, err := runcontrol.OpenSQLite(deps.ctx, root.Path, runcontrol.SQLiteOptions{})
		if err != nil {
			return classifiedCause(ExitWorkspace, err, "storage.migrate: open workspace database")
		}
		defer repository.Close()
		if _, err := productstate.Ensure(root.Path); err != nil {
			return classifiedCause(ExitWorkspace, err, "storage.migrate: create product-state schema")
		}
	}
	result := storageMigrationResult{SchemaVersion: 1, DryRun: dryRun, Items: []storageMigrationItem{}}
	appendItem := func(item storageMigrationItem) {
		result.Items = append(result.Items, item)
		switch item.Status {
		case "imported", "would_import":
			result.Imported++
		case "skipped":
			result.Skipped++
		case "failed":
			result.Failed++
		}
	}
	studies, err := study.DiscoverStudies(root.Path)
	if err != nil {
		return classifiedCause(ExitWorkspace, err, "storage.migrate: discover studies")
	}
	for _, item := range studies {
		path := study.RunStatePath(item)
		if _, err := os.Stat(path); err != nil {
			if !os.IsNotExist(err) {
				appendItem(storageMigrationItem{Kind: "study_run", Scope: item.Name, Path: path, Status: "failed", Error: err.Error()})
			}
			continue
		}
		stored, err := study.RunStateInDatabase(item)
		if err != nil {
			appendItem(storageMigrationItem{Kind: "study_run", Scope: item.Name, Path: path, Status: "failed", Error: err.Error()})
			continue
		}
		if stored {
			appendItem(storageMigrationItem{Kind: "study_run", Scope: item.Name, Path: path, Status: "skipped"})
			continue
		}
		state, err := study.LoadRunState(item)
		if err == nil && !dryRun {
			err = study.MigrateRunStateToDatabase(item, state)
		}
		appendItem(migrationItem("study_run", item.Name, path, dryRun, err))
	}
	projects, err := project.DiscoverProjects(root.Path)
	if err != nil {
		return classifiedCause(ExitWorkspace, err, "storage.migrate: discover projects")
	}
	for _, projectItem := range projects {
		sprints, err := sprint.DiscoverSprints(root.Path, projectItem)
		if err != nil {
			appendItem(storageMigrationItem{Kind: "project", Scope: projectItem.Name, Path: projectItem.Path, Status: "failed", Error: err.Error()})
			continue
		}
		for _, sprintItem := range sprints {
			migrateSprintState(root.Path, sprintItem, dryRun, appendItem)
		}
	}
	if jsonOut {
		if err := json.NewEncoder(deps.stdout).Encode(result); err != nil {
			return err
		}
	} else {
		for _, item := range result.Items {
			fmt.Fprintf(deps.stdout, "%-12s %-14s %s %s", item.Status, item.Kind, item.Scope, filepath.ToSlash(item.Path))
			if item.Error != "" {
				fmt.Fprintf(deps.stdout, " | %s", item.Error)
			}
			fmt.Fprintln(deps.stdout)
		}
		fmt.Fprintf(deps.stdout, "Product-state migration: %d imported, %d skipped, %d failed\n", result.Imported, result.Skipped, result.Failed)
	}
	if result.Failed > 0 {
		return classified(ExitPartial, "storage.migrate: %d state artifact(s) failed validation or import", result.Failed)
	}
	return nil
}

func migrateSprintState(root string, sp sprint.Sprint, dryRun bool, appendItem func(storageMigrationItem)) {
	scope := sp.Project + "/" + sp.Slug
	flowPath, flowPathErr := sprint.FlowStatePath(root, sp)
	if flowPathErr == nil {
		if _, err := os.Stat(flowPath); err == nil {
			stored, checkErr := sprint.FlowStateInDatabase(root, sp)
			if checkErr != nil {
				appendItem(storageMigrationItem{Kind: "sprint_flow", Scope: scope, Path: flowPath, Status: "failed", Error: checkErr.Error()})
			} else if stored {
				appendItem(storageMigrationItem{Kind: "sprint_flow", Scope: scope, Path: flowPath, Status: "skipped"})
			} else {
				state, loadErr := sprint.LoadFlowState(root, sp)
				if loadErr == nil && !dryRun {
					loadErr = sprint.MigrateFlowStateToDatabase(root, sp, state)
				}
				appendItem(migrationItem("sprint_flow", scope, flowPath, dryRun, loadErr))
			}
		} else if !os.IsNotExist(err) {
			appendItem(storageMigrationItem{Kind: "sprint_flow", Scope: scope, Path: flowPath, Status: "failed", Error: err.Error()})
		}
	}
	executePath, executePathErr := sprint.ExecuteRunStatePath(root, sp)
	if executePathErr == nil {
		if _, err := os.Stat(executePath); err == nil {
			if _, legacy := sprint.LegacyTerminalExecuteStatus(root, sp); legacy {
				appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "skipped"})
				return
			}
			stored, checkErr := sprint.ExecuteStateInDatabase(root, sp)
			if checkErr != nil {
				appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "failed", Error: checkErr.Error()})
			} else if stored {
				appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "skipped"})
			} else {
				state, loadErr := sprint.LoadExecuteRunState(root, sp)
				if loadErr == nil && !dryRun {
					loadErr = sprint.MigrateExecuteStateToDatabase(root, sp, state)
				}
				appendItem(migrationItem("sprint_execute", scope, executePath, dryRun, loadErr))
			}
		} else if !os.IsNotExist(err) {
			appendItem(storageMigrationItem{Kind: "sprint_execute", Scope: scope, Path: executePath, Status: "failed", Error: err.Error()})
		}
	}
}

func migrationItem(kind, scope, path string, dryRun bool, err error) storageMigrationItem {
	if err != nil {
		return storageMigrationItem{Kind: kind, Scope: scope, Path: path, Status: "failed", Error: err.Error()}
	}
	status := "imported"
	if dryRun {
		status = "would_import"
	}
	return storageMigrationItem{Kind: kind, Scope: scope, Path: path, Status: status}
}

func storageHelp() string {
	return `ultraplan storage migrate

Usage:
  ultraplan [--workspace <path>] storage migrate [--dry-run] [--json]

Imports existing study run state, sprint flow state, and sprint execute state
into the workspace SQLite database. Existing files remain as checkpoints.
`
}

package app

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"net"
	"strconv"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

const DefaultServeListen = "127.0.0.1:8080"

func runServe(deps dependencies, args []string) error {
	fs := flag.NewFlagSet("serve", flag.ContinueOnError)
	fs.SetOutput(deps.stderr)
	listen := fs.String("listen", DefaultServeListen, "numeric loopback listen address")
	openBrowser := fs.Bool("open-browser", false, "open the dashboard in the default browser")
	fs.Usage = func() { _, _ = deps.stdout.Write([]byte(serveHelp())) }
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return classified(ExitUsage, "serve: %w", err)
	}
	if fs.NArg() != 0 {
		return classified(ExitUsage, "serve: unexpected argument %q", fs.Arg(0))
	}
	if err := ValidateLoopbackListen(*listen); err != nil {
		return classified(ExitUsage, "serve.listen: %w", err)
	}

	root, err := discoverWorkspace(deps)
	if err != nil {
		return err
	}
	effective, err := loadEffectiveConfig(root, deps, configOverridesForServe())
	if err != nil {
		return err
	}
	qa, err := qaSettings(effective)
	if err != nil {
		return classified(ExitConfig, "qa.config: %w", err)
	}
	rt, err := studyRuntimeFactory(effective.Config)
	if err != nil {
		return classified(ExitRuntime, "runtime.init: %w", err)
	}
	if deps.webRunner == nil {
		return classified(ExitError, "serve.start: web runner is not configured")
	}
	dashboard := dashboardUseCases{
		root: root.Path, stageRuntime: planningStageRuntime(effective.Config),
		reviewConcurrency: effective.Config.Execution.DefaultParallel,
		smokeSettings:     smokeSettings(effective, envLookup(deps.env)), readOnly: true,
		qaSettings: qa,
	}
	if errors.Is(deps.ctx.Err(), context.Canceled) {
		return nil
	}
	repository, _, err := runRepository(deps)
	if err != nil {
		return err
	}
	defaultModel := firstNonEmptyWorkspaceModel(effective.Config)
	var modelsLister RuntimeModelLister
	if adapter, ok := any(rt).(runtimepkg.Adapter); ok {
		modelsLister = adapter
	}
	useCases := NewWebUseCases(root.Path, WebUseCaseOptions{
		StageRuntime:      planningStageRuntime(effective.Config),
		ReviewConcurrency: effective.Config.Execution.DefaultParallel,
		SmokeSettings:     smokeSettings(effective, envLookup(deps.env)),
		QASettings:        qa,
		Runner:            sharedOperationRunner(deps, root, effective, dashboard),
		RunControl:        repositoryRunUseCases{repository: repository},
		DurableOperations: newDurableOperationManager(repository, deps.runControl.owner),
		DefaultModel:      defaultModel,
		Models:            modelsLister,
	})
	err = deps.webRunner(deps.ctx, ServeRunOptions{
		Listen:      *listen,
		OpenBrowser: *openBrowser,
		UseCases:    useCases,
		Stdout:      deps.stdout,
		Diagnostics: deps.stderr,
	})
	if err == nil {
		return nil
	}
	if errors.Is(err, context.Canceled) && errors.Is(deps.ctx.Err(), context.Canceled) {
		return nil
	}
	return classifiedCause(ExitError, err, "serve.start")
}

// firstNonEmptyWorkspaceModel returns the workspace-configured default model
// reference shown as the selection default on model surfaces.
func firstNonEmptyWorkspaceModel(c config.Config) string {
	if strings.TrimSpace(c.Models.Primary) != "" {
		return strings.TrimSpace(c.Models.Primary)
	}
	return strings.TrimSpace(c.Models.Default)
}

// configOverridesForServe exists to make it explicit that serve uses the
// normal workspace/environment config validation without adding hidden web
// configuration sources in this sprint.
func configOverridesForServe() config.CLIOverrides {
	return config.CLIOverrides{}
}

// ValidateLoopbackListen accepts numeric IPv4 loopback literals or bracketed
// IPv6 loopback literals with an explicit non-zero port.
func ValidateLoopbackListen(value string) error {
	if strings.TrimSpace(value) != value || value == "" {
		return errors.New("listen address is required")
	}
	host, port, err := net.SplitHostPort(value)
	if err != nil {
		return fmt.Errorf("use a numeric loopback IP and explicit port: %w", err)
	}
	if strings.Contains(host, "%") {
		return errors.New("IPv6 zones are not supported")
	}
	ip := net.ParseIP(host)
	if ip == nil || !ip.IsLoopback() {
		return errors.New("listen address must use a numeric loopback IP such as 127.0.0.1 or [::1]")
	}
	n, err := strconv.Atoi(port)
	if err != nil || n < 1 || n > 65535 {
		return errors.New("listen port must be between 1 and 65535")
	}
	return nil
}

func serveHelp() string {
	return `ultraplan serve

Usage:
  ultraplan [--workspace <path>] serve [--listen <address>] [--open-browser]

Starts the guarded local browser dashboard. The server accepts only numeric
loopback addresses, exposes allowlisted app operations with current
confirmation and bounded SSE progress, and shuts down owned operations
gracefully on interrupt or process cancellation.

Options:
  --listen <address>   Loopback IP and port (default 127.0.0.1:8080).
  --open-browser       Open the canonical dashboard URL after listening.
  --workspace <path>   Select the workspace (global flag).
  -h, --help           Show help without starting a listener.
`
}

package app

import (
	"errors"
	"fmt"

	"github.com/Antonio7098/ultraplan-go/internal/project"
)

func runProject(deps dependencies, args []string) error {
	if len(args) == 0 {
		return classified(ExitUsage, "project requires a subcommand\n\nRun 'ultraplan project --help' for usage.")
	}
	if args[0] == "--help" || args[0] == "-h" {
		_, err := deps.stdout.Write([]byte(projectHelp()))
		return err
	}
	if len(args) >= 2 && args[0] == "list" && (args[1] == "--help" || args[1] == "-h") {
		_, err := deps.stdout.Write([]byte(projectListHelp()))
		return err
	}
	if len(args) >= 3 && (args[2] == "--help" || args[2] == "-h") {
		switch args[1] {
		case "status":
			_, err := deps.stdout.Write([]byte(projectStatusHelp()))
			return err
		case "validate":
			_, err := deps.stdout.Write([]byte(projectValidateHelp()))
			return err
		}
	}
	root, err := discoverWorkspace(deps)
	if err != nil {
		return err
	}
	service := project.NewService(root.Path)
	switch {
	case len(args) == 1 && args[0] == "list":
		projects, err := service.ListProjects()
		if err != nil {
			return mapProjectError("project.list", err)
		}
		fmt.Fprintf(deps.stdout, "Workspace: %s\n", root.Path)
		fmt.Fprintln(deps.stdout, "Projects:")
		if len(projects) == 0 {
			fmt.Fprintln(deps.stdout, "  (none)")
			return nil
		}
		for _, item := range projects {
			fmt.Fprintf(deps.stdout, "  %s\n", item.Name)
		}
		return nil
	case len(args) == 2 && args[1] == "status":
		status, err := service.Status(args[0])
		if err != nil {
			return mapProjectError("project.status", err)
		}
		renderProjectStatus(deps, status)
		return nil
	case len(args) == 2 && args[1] == "validate":
		result, err := service.Validate(args[0])
		if err != nil {
			return mapProjectError("project.validate", err)
		}
		renderProjectValidation(deps, result)
		if len(result.Findings) > 0 {
			return classedError{class: ExitValidation, code: errorCode(ExitValidation), err: fmt.Errorf("project.validate: validation failed")}
		}
		return nil
	case args[0] == "list":
		return classified(ExitUsage, "project list: unknown argument %q", args[1])
	default:
		return classified(ExitUsage, "project: expected 'list', '<project> status', or '<project> validate'")
	}
}

func mapProjectError(prefix string, err error) error {
	var refErr project.RefError
	if errors.As(err, &refErr) {
		return classified(ExitValidation, "%s: %w", prefix, err)
	}
	return classified(ExitWorkspace, "%s: %w", prefix, err)
}

func renderProjectStatus(deps dependencies, status project.ProjectStatus) {
	fmt.Fprintf(deps.stdout, "Project: %s\n", status.Project.Name)
	fmt.Fprintf(deps.stdout, "Docs: %s\n", status.DocsDir)
	fmt.Fprintf(deps.stdout, "Markdown docs: %d\n", len(status.MarkdownDocs))
	for _, doc := range status.MarkdownDocs {
		fmt.Fprintf(deps.stdout, "  %s\n", doc)
	}
	fmt.Fprintf(deps.stdout, "Roadmap: %s\n", status.Roadmap)
	fmt.Fprintf(deps.stdout, "Project index: %s\n", status.ProjectIndex)
	fmt.Fprintf(deps.stdout, "Sprints: %s\n", status.SprintsDir)
	fmt.Fprintf(deps.stdout, "Sprint directories: %d\n", len(status.SprintDirs))
	for _, sprint := range status.SprintDirs {
		fmt.Fprintf(deps.stdout, "  %s\n", sprint)
	}
	fmt.Fprintln(deps.stdout, "Reasoning defaults:")
	for _, item := range status.ReasoningDefaults {
		fmt.Fprintf(deps.stdout, "  %s: %s\n", item.RelativePath, item.Source)
	}
	fmt.Fprintf(deps.stdout, "Project area reasoning documents: %d\n", len(status.AreaReasoningDocuments))
	for _, path := range status.AreaReasoningDocuments {
		fmt.Fprintf(deps.stdout, "  %s\n", path)
	}
	fmt.Fprintf(deps.stdout, "Catalog: %s\n", status.Catalog)
	if len(status.ValidationFinds) > 0 {
		fmt.Fprintf(deps.stdout, "Findings: %d\n", len(status.ValidationFinds))
	}
}

func renderProjectValidation(deps dependencies, result project.ValidationResult) {
	fmt.Fprintf(deps.stdout, "Project: %s\n", result.Project.Name)
	fmt.Fprintf(deps.stdout, "Validation: %s\n", result.Status)
	fmt.Fprintf(deps.stdout, "Findings: %d\n", len(result.Findings))
	for _, finding := range result.Findings {
		fmt.Fprintf(deps.stderr, "%s", finding.Severity)
		if finding.Section != "" {
			fmt.Fprintf(deps.stderr, " section=%q", finding.Section)
		}
		if finding.EntryName != "" {
			fmt.Fprintf(deps.stderr, " entry=%q", finding.EntryName)
		}
		if finding.Path != "" {
			fmt.Fprintf(deps.stderr, " path=%q", finding.Path)
		}
		fmt.Fprintf(deps.stderr, " problem=%q cause=%q suggestion=%q\n", finding.Problem, finding.Cause, finding.Suggestion)
	}
}

func projectHelp() string {
	return `ultraplan project

Usage:
  ultraplan project list
  ultraplan project <project> status
  ultraplan project <project> validate

Commands:
  list                List discovered project roots.
  <project> status    Show project docs, roadmap, index, sprints, and catalog health.
  <project> validate  Validate project files and project-index.md catalog references.
`
}

func projectListHelp() string {
	return `ultraplan project list

Usage:
  ultraplan project list

Lists direct non-hidden project roots under projects/.
`
}

func projectStatusHelp() string {
	return `ultraplan project <project> status

Usage:
  ultraplan project <project> status

Shows read-only project planning root health without runtime execution.
`
}

func projectValidateHelp() string {
	return `ultraplan project <project> validate

Usage:
  ultraplan project <project> validate

Validates required project files and project-index.md catalog paths.
`
}

